import static org.junit.jupiter.api.Assertions.assertEquals;

import java.io.ByteArrayOutputStream;
import java.io.PrintStream;
import java.lang.reflect.Field;

public class LogRoleTests {

    private void setEnabled(DefaultLogger logger, boolean enabled) throws Exception {
        Field f = DefaultLogger.class.getDeclaredField("enabled");
        f.setAccessible(true);
        f.setBoolean(logger, enabled);
    }

    @Test
    public void testLogRole_enabledPrintsRoles() throws Exception {
        DefaultLogger logger = new DefaultLogger();
        setEnabled(logger, true);

        String[] roles = new String[] { "admin", "user", "guest" };

        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        PrintStream originalOut = System.out;
        try {
            System.setOut(new PrintStream(baos, true, "UTF-8"));
            logger.logRole(roles);
        } finally {
            System.setOut(originalOut);
        }

        String output = baos.toString("UTF-8");
        String expected = "Roles: " + String.join("\n", roles) + System.lineSeparator();
        assertEquals(expected, output);
    }

    @Test
    public void testLogRole_disabledPrintsNothing() throws Exception {
        DefaultLogger logger = new DefaultLogger();
        setEnabled(logger, false);

        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        PrintStream originalOut = System.out;
        try {
            System.setOut(new PrintStream(baos, true, "UTF-8"));
            logger.logRole(new String[] { "admin", "user" });
        } finally {
            System.setOut(originalOut);
        }

        String output = baos.toString("UTF-8");
        assertEquals("", output);
    }
}

