package org.casbin.jcasbin.log;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

import java.io.ByteArrayOutputStream;
import java.io.PrintStream;
import java.lang.reflect.Field;
import java.util.LinkedHashMap;
import java.util.Map;

public class LogPolicyTests {

    private String captureOutput(Runnable r) {
        PrintStream originalOut = System.out;
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        PrintStream ps = new PrintStream(baos);
        System.setOut(ps);
        try {
            r.run();
        } finally {
            System.out.flush();
            System.setOut(originalOut);
        }
        return baos.toString();
    }

    private void setEnabled(DefaultLogger logger, boolean value) throws Exception {
        Field f = DefaultLogger.class.getDeclaredField("enabled");
        f.setAccessible(true);
        f.setBoolean(logger, value);
    }

    @Test
    public void testLogPolicyPrintsWhenEnabled() throws Exception {
        DefaultLogger logger = new DefaultLogger();
        setEnabled(logger, true);

        Map<String, String[][]> policy = new LinkedHashMap<>();
        policy.put("p", new String[][] { {"alice","data1","read"} });
        policy.put("g", new String[][] { {"alice","data1"} });

        String output = captureOutput(() -> {
            logger.logPolicy(policy);
        });

        assertTrue(output.startsWith("Policy: "));
        assertTrue(output.contains("p :"));
        assertTrue(output.contains("g :"));
        int newlineCount = output.split(System.lineSeparator(), -1).length - 1;
        assertTrue(newlineCount >= 1);
    }

    @Test
    public void testLogPolicyDoesNotPrintWhenDisabled() throws Exception {
        DefaultLogger logger = new DefaultLogger();
        Field f = DefaultLogger.class.getDeclaredField("enabled");
        f.setAccessible(true);
        f.setBoolean(logger, false);

        Map<String, String[][]> policy = new LinkedHashMap<>();
        policy.put("p", new String[][] { {"alice","data1","read"} });

        String output = captureOutput(() -> {
            logger.logPolicy(policy);
        });

        assertEquals("", output);
    }

    @Test
    public void testLogPolicyPrintsEmptyPolicy() throws Exception {
        DefaultLogger logger = new DefaultLogger();
        setEnabled(logger, true);

        Map<String, String[][]> policy = new LinkedHashMap<>();

        String output = captureOutput(() -> {
            logger.logPolicy(policy);
        });

        String expected = "Policy: " + System.lineSeparator();
        assertEquals(expected, output);
    }
}

