package org.casbin.jcasbin.main;

import org.casbin.jcasbin.model.Model;
import org.casbin.jcasbin.persist.UpdatableAdapter;
import org.junit.jupiter.api.Test;

import java.lang.reflect.Field;
import java.util.Arrays;
import java.util.List;
import java.util.function.BooleanSupplier;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

public class UpdatePolicySelfTests {

    // Fake Model to control updatePolicy behavior
    static class FakeModel extends Model {
        boolean updated;
        boolean updatePolicyReturn = true;

        @Override
        public boolean updatePolicy(String sec, String ptype, List<String> oldRule, List<String> newRule) {
            updated = true;
            return updatePolicyReturn;
        }
    }

    // Helper to set fields on superclass via reflection
    private void setFieldInHierarchy(Object target, String fieldName, Object value) throws Exception {
        Class<?> cls = target.getClass();
        Field f = null;
        while (cls != null) {
            try {
                f = cls.getDeclaredField(fieldName);
                break;
            } catch (NoSuchFieldException e) {
                cls = cls.getSuperclass();
            }
        }
        if (f == null) {
            throw new NoSuchFieldException(fieldName);
        }
        f.setAccessible(true);
        f.set(target, value);
    }

    @Test
    public void testUpdatePolicySelf_PersistsWithUpdatableAdapter_Succeeds() throws Exception {
        DistributedEnforcer de = new DistributedEnforcer();
        FakeModel model = new FakeModel();
        model.updatePolicyReturn = true;

        UpdatableAdapter adapter = mock(UpdatableAdapter.class);

        setFieldInHierarchy(de, "model", model);
        setFieldInHierarchy(de, "adapter", adapter);

        List<String> oldRule = Arrays.asList("alice", "data1", "read");
        List<String> newRule = Arrays.asList("alice", "data1", "read2");

        boolean result = de.updatePolicySelf((BooleanSupplier) () -> true, "p", "p", oldRule, newRule);

        assertTrue(result, "updatePolicySelf should return true when model updatePolicy returns true");
        assertTrue(model.updated, "Model.updatePolicy should be invoked");
        verify(adapter).updatePolicy(eq("p"), eq("p"), eq(oldRule), eq(newRule));
    }

    @Test
    public void testUpdatePolicySelf_PersistsWithUpdatableAdapter_ThrowsUnsupported() throws Exception {
        DistributedEnforcer de = new DistributedEnforcer();
        FakeModel model = new FakeModel();
        model.updatePolicyReturn = true;

        UpdatableAdapter adapter = mock(UpdatableAdapter.class);
        doThrow(new UnsupportedOperationException("Not implemented")).when(adapter).updatePolicy(anyString(), anyString(), anyList(), anyList());

        setFieldInHierarchy(de, "model", model);
        setFieldInHierarchy(de, "adapter", adapter);

        List<String> oldRule = Arrays.asList("alice", "data1", "read");
        List<String> newRule = Arrays.asList("alice", "data1", "read2");

        boolean result = de.updatePolicySelf((BooleanSupplier) () -> true, "p", "p", oldRule, newRule);

        assertTrue(result, "Should still return true when adapter method not implemented");
        assertTrue(model.updated, "Model.updatePolicy should be invoked even if adapter fails");
    }

    @Test
    public void testUpdatePolicySelf_NoPersistAdapterNotCalled() throws Exception {
        DistributedEnforcer de = new DistributedEnforcer();
        FakeModel model = new FakeModel();
        model.updatePolicyReturn = true;

        UpdatableAdapter adapter = mock(UpdatableAdapter.class);
        setFieldInHierarchy(de, "model", model);
        setFieldInHierarchy(de, "adapter", adapter);

        List<String> oldRule = Arrays.asList("alice", "data1", "read");
        List<String> newRule = Arrays.asList("alice", "data1", "read2");

        boolean result = de.updatePolicySelf((BooleanSupplier) () -> false, "p", "p", oldRule, newRule);

        assertTrue(result, "Model updatePolicy should decide final result when persistence is disabled");
        verify(adapter, never()).updatePolicy(anyString(), anyString(), anyList(), anyList());
        assertTrue(model.updated, "Model.updatePolicy should be invoked when persistence is disabled depending");
    }
}

