import java.lang.reflect.Method;
import java.lang.reflect.Modifier;
import java.util.HashMap;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.*;

public class PrintModelTests {

    private boolean setModelField(Model model, Map<String, Map<String, Assertion>> value) {
        try {
            Field f = Model.class.getDeclaredField("model");
            f.setAccessible(true);
            f.set(model, value);
            return true;
        } catch (NoSuchFieldException | IllegalAccessException ex) {
            // Fallback: try any Map field
        }
        for (Field f : Model.class.getDeclaredFields()) {
            if (Map.class.isAssignableFrom(f.getType())) {
                f.setAccessible(true);
                try {
                    f.set(model, value);
                    return true;
                } catch (IllegalAccessException ignored) {
                }
            }
        }
        return false;
    }

    private boolean setUtilLog(boolean enabled) {
        String[] utilClassNames = {
            "org.casbin.jcasbin.Util",
            "org.casbin.jcasbin.util.Util",
            "org.casbin.jcasbin.util.TestUtil"
        };
        for (String name : utilClassNames) {
            try {
                Class<?> utilClass = Class.forName(name);
                try {
                    Method m = utilClass.getDeclaredMethod("setLogPrintEnabled", boolean.class);
                    m.setAccessible(true);
                    m.invoke(null, enabled);
                    return true;
                } catch (NoSuchMethodException | IllegalAccessException | java.lang.reflect.InvocationTargetException ignored) {
                }
                for (Field f : utilClass.getDeclaredFields()) {
                    int mods = f.getModifiers();
                    if (Modifier.isStatic(mods) && !Modifier.isFinal(mods)
                            && (f.getType() == boolean.class || f.getType() == Boolean.class)) {
                        f.setAccessible(true);
                        f.set(null, enabled);
                        return true;
                    }
                }
            } catch (ClassNotFoundException ignored) {
            } catch (Exception ignored) {
            }
        }
        return false;
    }

    @Test
    void testPrintModel_outputs_all_entries_when_logging_enabled() throws Exception {
        Assumptions.assumeTrue(setUtilLog(true), "Unable to enable Util log printing");

        PrintStream originalOut = System.out;
        PrintStream originalErr = System.err;
        ByteArrayOutputStream outBaos = new ByteArrayOutputStream();
        ByteArrayOutputStream errBaos = new ByteArrayOutputStream();
        System.setOut(new PrintStream(outBaos));
        System.setErr(new PrintStream(errBaos));

        Model model = new Model();
        Map<String, Map<String, Assertion>> m = new HashMap<>();
        Map<String, Assertion> innerR = new HashMap<>();
        Assertion a1 = new Assertion();
        a1.value = "alice";
        innerR.put("sub", a1);
        m.put("r", innerR);
