        model.printModel();

        System.out.flush();
        System.out.flush(System.err);
        System.setOut(originalOut);
        System.setErr(originalErr);

        String output = outBaos.toString() + errBaos.toString();

        assertTrue(output.contains("Model:"));
        assertTrue(output.contains("r.sub: alice"));
        assertTrue(output.contains("p.sub: data"));
    }

    @Test
