import static org.junit.jupiter.api.Assertions.*;

import java.io.IOException;
import java.lang.reflect.Field;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.concurrent.atomic.AtomicBoolean;

public class EnforceTests {

    // Helper to create a temporary model and policy files
    private static class TempModelPolicy {
        Path modelPath;
        Path policyPath;

        TempModelPolicy(Path modelPath, Path policyPath) {
            this.modelPath = modelPath;
            this.policyPath = policyPath;
        }
    }

    private TempModelPolicy createModelAndPolicyFiles() throws IOException {
        String modelContent =
                "[request_definition]\n" +
                "r = sub, obj, act\n" +
                "[policy_definition]\n" +
                "p = sub, obj, act\n" +
                "[policy_effect]\n" +
                "e = some(where (p.eft == allow))\n" +
                "[matchers]\n" +
                "m = r.sub == p.sub && r.obj == p.obj && r.act == p.act\n";

        String policyContent = "p, alice, data1, read\n";

        Path modelPath = Files.createTempFile("casbin-model-", ".conf");
        Path policyPath = Files.createTempFile("casbin-policy-", ".policy");
        Files.write(modelPath, modelContent.getBytes(StandardCharsets.UTF_8));
        Files.write(policyPath, policyContent.getBytes(StandardCharsets.UTF_8));
        return new TempModelPolicy(modelPath, policyPath);
    }

    // Test 1: Ensure getKey is called and key is null branch triggers enforcement path
    public static class KeyNullEnforcer extends CachedEnforcer {
        boolean keyNullUsed = false;

        public KeyNullEnforcer(String modelPath, String policyFile) {
            super(modelPath, policyFile);
        }

        @Override
        protected String getKey(Object... rvals) {
            keyNullUsed = true;
            return null;
        }

        public boolean wasKeyNull() {
            return keyNullUsed;
        }
    }

    @Test
    public void testEnforceKeyNullBranch() throws Exception {
        TempModelPolicy tmp = createModelAndPolicyFiles();
        try {
            KeyNullEnforcer enforcer = new KeyNullEnforcer(tmp.modelPath.toString(), tmp.policyPath.toString());
            boolean result = enforcer.enforce("alice", "data1", "read");
            assertTrue(result, "Enforce with key == null should still return true given policy");
            assertTrue(enforcer.wasKeyNull(), "getKey should have been invoked and returned null");
        } finally {
            Files.deleteIfExists(tmp.modelPath);
            Files.deleteIfExists(tmp.policyPath);
        }
    }

    // Test 2: Ensure cached result path is used (getCachedResult returns non-null)
    public static class CachedResultEnforcer extends CachedEnforcer {
        int cachedCalls = 0;

        public CachedResultEnforcer(String modelPath, String policyFile) {
            super(modelPath, policyFile);
        }

        @Override
        protected Boolean getCachedResult(String key) {
            cachedCalls++;
            return Boolean.TRUE; // simulate cached positive result
        }

        public int getCachedCalls() {
            return cachedCalls;
        }
    }

    @Test
    public void testEnforceUsesCachedResultBranch() throws Exception {
        TempModelPolicy tmp = createModelAndPolicyFiles();
        try {
            CachedResultEnforcer enforcer = new CachedResultEnforcer(tmp.modelPath.toString(), tmp.policyPath.toString());
            boolean result = enforcer.enforce("alice", "data1", "read");
            assertTrue(result, "Enforce should return cached result (true)");
            assertTrue(enforcer.getCachedCalls() >= 1, "getCachedResult should have been invoked at least once");
        } finally {
            Files.deleteIfExists(tmp.modelPath);
            Files.deleteIfExists(tmp.policyPath);
        }
    }

    // Test 3: Ensure when enableCache is false, getKey is not called
    public static class KeyCounterEnforcer extends CachedEnforcer {
        int keyCount = 0;

        public KeyCounterEnforcer(String modelPath, String policyFile) {
            super(modelPath, policyFile);
        }

        @Override
        protected String getKey(Object... rvals) {
            keyCount++;
            return super.getKey(rvals);
        }

        public int getKeyCount() {
            return keyCount;
        }
    }

    @Test
    public void testEnforceDisableCacheNoKeyCall() throws Exception {
        TempModelPolicy tmp = createModelAndPolicyFiles();
        try {
            KeyCounterEnforcer enforcer = new KeyCounterEnforcer(tmp.modelPath.toString(), tmp.policyPath.toString());

            // Use reflection to set enableCache to false
            Class<?> cls = enforcer.getClass().getSuperclass(); // CachedEnforcer
            Field field = cls.getDeclaredField("enableCache");
            field.setAccessible(true);
            field.set(enforcer, new AtomicBoolean(false));

            boolean res = enforcer.enforce("alice", "data1", "read");

            // Even if policy would allow, we focus on whether getKey was called when cache is disabled
            assertFalse(enforcer.getKeyCount() > 0, "getKey should not be called when cache is disabled");
        } finally {
            Files.deleteIfExists(tmp.modelPath);
            Files.deleteIfExists(tmp.policyPath);
        }
    }
}

