package org.casbin.jcasbin.rbac;

import java.util.function.BiPredicate;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

public class MatchTests {

    public static class CountingPredicate implements BiPredicate<String, String> {
        public int count = 0;

        @Override
        public boolean test(String s, String p) {
            count++;
            return s != null && s.equals(p);
        }
    }

    @Test
    public void testMatchWithNoPredicateUsesEqualityAndCaches() {
        DefaultRoleManager drm = new DefaultRoleManager(2);
        assertTrue(drm.match("alice", "alice"));
        assertFalse(drm.match("alice", "bob"));
        // Cached result should be returned without error
        assertTrue(drm.match("alice", "alice"));
    }

    @Test
    public void testMatchWithCustomPredicateCachesSingleInvocation() {
        CountingPredicate cp = new CountingPredicate();
        DefaultRoleManager drm = new DefaultRoleManager(2, cp, null);

        assertFalse(drm.match("a", "b"));
        assertEquals(1, cp.count);

        // Second call with same inputs should hit cache and not call predicate again
        assertFalse(drm.match("a", "b"));
        assertEquals(1, cp.count);
    }

    @Test
    public void testMatchWithCustomPredicateCachesSeparateKeys() {
        CountingPredicate cp = new CountingPredicate();
        DefaultRoleManager drm = new DefaultRoleManager(2, cp, null);

        // First distinct key
        assertFalse(drm.match("x", "y"));
        assertEquals(1, cp.count);

        // Second distinct key
        assertTrue(drm.match("x", "x"));
        assertEquals(2, cp.count);
    }
}

